package com.abhishek.youtubesubtitledownloader.domain.model

/**
 * Sealed class representing the result of a subtitle download operation
 */
sealed class SubtitleResult {
    /**
     * Successful subtitle download
     * @param text The subtitle text without timestamps
     * @param language The language code of the downloaded subtitle
     * @param videoTitle The video title, or null when YouTube did not return one
     * @param languageName The display name of the downloaded track (e.g., "Indonesian")
     * @param isAutoGenerated Whether the downloaded track was generated by YouTube from the speech
     * @param requestedLanguageMatched False when none of the requested languages existed
     *        and the first available track was used instead
     * @param availableTracks Every caption track the video offers, including the downloaded one
     */
    data class Success(
        val text: String,
        val language: String,
        val videoTitle: String? = null,
        val languageName: String = language,
        val isAutoGenerated: Boolean = false,
        val requestedLanguageMatched: Boolean = true,
        val availableTracks: List<CaptionTrack> = emptyList()
    ) : SubtitleResult()

    /**
     * Error during subtitle download
     * @param type The type of error that occurred
     * @param message Human-readable error message
     * @param throwable Optional throwable for debugging
     */
    data class Error(
        val type: ErrorType,
        val message: String,
        val throwable: Throwable? = null
    ) : SubtitleResult()

    /**
     * Loading state (optional, for UI progress indication)
     * @param progress Optional progress message
     */
    data class Loading(val progress: String? = null) : SubtitleResult()
}

/**
 * One caption track a video offers
 *
 * @param languageCode YouTube caption code (e.g., "en", "es-419")
 * @param name Display name YouTube gives the track (e.g., "Spanish (Latin America)")
 * @param isAutoGenerated Whether YouTube generated the track from the speech
 */
data class CaptionTrack(
    val languageCode: String,
    val name: String,
    val isAutoGenerated: Boolean
)

/**
 * Types of errors that can occur during subtitle download
 */
enum class ErrorType {
    /**
     * The provided URL is not a valid YouTube URL
     */
    INVALID_URL,

    /**
     * Failed to extract video ID from URL
     */
    INVALID_VIDEO_ID,

    /**
     * Network error (timeout, no connection, etc.)
     */
    NETWORK_ERROR,

    /**
     * Failed to fetch or extract INNERTUBE_API_KEY
     */
    API_KEY_EXTRACTION_FAILED,

    /**
     * Failed to get caption tracks from InnerTube API
     */
    CAPTION_TRACKS_NOT_FOUND,

    /**
     * No subtitles available for the video
     */
    NO_SUBTITLES_AVAILABLE,

    /**
     * Requested language not available
     */
    LANGUAGE_NOT_AVAILABLE,

    /**
     * Failed to download transcript XML
     */
    TRANSCRIPT_DOWNLOAD_FAILED,

    /**
     * Failed to parse transcript XML
     */
    TRANSCRIPT_PARSE_FAILED,

    /**
     * YouTube rejected all known client versions. The app may need an update.
     */
    CLIENT_VERSION_OUTDATED,

    /**
     * Unknown error occurred
     */
    UNKNOWN_ERROR
}
